class ConfigFileSettingsSource(PydanticBaseSettingsSource):
    """
    A simple settings source that loads variables from a yaml file in GTO DIR
    """

    def __init__(
        self,
        settings_cls: Type[BaseSettings],
        config_file: Union[str, Path],
    ):
        super().__init__(settings_cls)
        self.config_file = Path(config_file)
        self.encoding = settings_cls.model_config.get("env_file_encoding") or "utf-8"

    def get_field_value(self, field, field_name):  # pylint: disable=unused-argument
        # values are loaded all at once in __call__
        return None, field_name, False

    def __call__(self) -> Dict[str, Any]:
        if not self.config_file.exists():
            return {}
        conf = yaml.load(self.config_file.read_text(encoding=self.encoding))

